import os, subprocess, sys, tempfile, unittest

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from tabula import engine

T = "city,qty,price\nLeeds,2,10.50\nHull,3,4\nLeeds,5,0.25\nYork,1,-3\nHull,4,1.5\n"


def run_cli(*argv, files=None):
    with tempfile.TemporaryDirectory() as d:
        for k, v in (files or {}).items():
            with open(os.path.join(d, k), "w", encoding="utf-8", newline="") as fh:
                fh.write(v)
        env = dict(os.environ, PYTHONPATH=os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
        p = subprocess.run([sys.executable, "-m", "tabula"] + list(argv), cwd=d, env=env, capture_output=True, text=True)
        return p.returncode, p.stdout, p.stderr


def group(*aggs, by="city", text=T):
    code, out, err = run_cli("--format=csv", "group", "t.csv", by, *aggs, files={"t.csv": text})
    assert code == 0, err
    return out


class GroupResultTests(unittest.TestCase):
    def test_aggregates(self):
        for aggs, want in [
            (["count"], "city,count\nLeeds,2\nHull,2\nYork,1\n"),
            (["sum:qty"], "city,sum_qty\nLeeds,7\nHull,7\nYork,1\n"),
            (["sum:price"], "city,sum_price\nLeeds,10.75\nHull,5.5\nYork,-3\n"),
            (["min:price", "max:price"], "city,min_price,max_price\nLeeds,0.25,10.50\nHull,1.5,4\nYork,-3,-3\n"),
            (["mean:qty"], "city,mean_qty\nLeeds,3.50\nHull,3.50\nYork,1.00\n"),
            (["mean:price"], "city,mean_price\nLeeds,5.38\nHull,2.75\nYork,-3.00\n"),   # 5.375 rounds half up
            (["max:qty", "count", "sum:qty"], "city,max_qty,count,sum_qty\nLeeds,5,2,7\nHull,4,2,7\nYork,1,1,1\n"),
        ]:
            with self.subTest(aggs):
                self.assertEqual(group(*aggs), want)

    def test_first_appearance_order_and_text_keys(self):
        self.assertEqual(group("count", by="k", text="k,v\nb,1\nB,2\nb,3\n,4\n"), "k,count\nb,2\nB,1\n,1\n")

    def test_number_output(self):
        text = "k,v\na,10.50\na,+0\nb,-0.00\nb,.5\nc, 7 \nd,5.\nd,5.\n"
        self.assertEqual(group("sum:v", "min:v", "max:v", "mean:v", by="k", text=text),
                         "k,sum_v,min_v,max_v,mean_v\na,10.50,0,10.50,5.25\nb,0.50,0.00,0.5,0.25\n"
                         "c,7,7,7,7.00\nd,10,5,5,5.00\n")

    def test_mean_half_up_negative_and_zero(self):
        # -2.125 -> -2.13 (half up rounds the tie away from zero); -0.001 -> 0.00, no sign
        self.assertEqual(group("mean:v", by="k", text="k,v\na,-2.125\nb,-0.001\nc,0.005\nd,1\nd,1\nd,2\n"),
                         "k,mean_v\na,-2.13\nb,0.00\nc,0.01\nd,1.33\n")

    def test_exact_arithmetic(self):
        big = "1" * 40 + ".0000000000000000000000000000000001"
        text = "k,v\na,%s\na,1\n" % big
        self.assertEqual(group("sum:v", by="k", text=text).splitlines()[1], "a," + "1" * 39 + "2.0000000000000000000000000000000001")
        huge = "9" * 5000
        out = group("sum:v", "mean:v", by="k", text="k,v\na,%s\na,1\n" % huge).splitlines()[1].split(",")
        self.assertEqual(out[1], "1" + "0" * 5000)
